254	    @Override
255	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
256	        Owner owner = this.clinicService.findOwnerById(ownerId);
257	        if (owner == null) {
258	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
259	        }
260	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
261	        applyBulkSignupWarning(ownerDto);
