267	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
268	    @Override
269	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
270	        ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
271	        if (replay != null) {
272	            return replay;
273	        }
274	        validateRequiredFields(ownerFieldsDto);
275	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
276	        LocalDate registrationDate = toBusinessDay(
277	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
278	        rejectDailyLimitReached(registrationDate);
279	        HttpHeaders headers = new HttpHeaders();
280	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
281	        applyAddress(owner, ownerFieldsDto);
282	        rejectCityAtCapacity(owner.getCity());
283	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
284	        owner.setTelephone(telephone);
285	        String email = normalizeEmail(ownerFieldsDto.getEmail());
286	        owner.setEmail(email);
287	        owner.setPostcode(validatePostcode(ownerFieldsDto.getPostcode(), regionForCity(owner.getCity())));
288	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
289	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
290	        rejectDuplicateIdentity(owner);
291	        applyPossibleDuplicate(owner, sharesHousehold);
292	        owner.setRegistrationDate(registrationDate);
293	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
294	        owner.setMemberId(generateMemberId(owner.getPostcode(), owner.getTelephone(),
295	            owner.getLastName(), owner.getRegistrationDate()));
296	        owner.setMembershipLevel(cappedMembershipLevel(owner));
297	        this.clinicService.saveOwner(owner);
298	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
299	            owner.getId(), primaryIdentifier(owner), owner.getRegistrationDate(),
300	            owner.getMembershipLevel());
301	        emitOwnerCreatedEvent(owner);
302	        enqueueWelcomeNotification(owner);
303	        rememberIdempotentCreate(idempotencyKey, owner.getId());
304	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
305	        applyBulkSignupWarning(ownerDto);
306	        applyCapacityWarning(ownerDto);
307	        applyRiskFlag(ownerDto);
308	        headers.setLocation(UriComponentsBuilder.newInstance()
309	            .path(OwnerMapper.OWNER_PATH_TEMPLATE).buildAndExpand(owner.getId()).toUri());
310	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
311	    }
312	
313	    /**
314	     * Serves a repeated create that carries an {@code Idempotency-Key} already seen on an earlier
315	     * successful create. When the key has a remembered owner that still exists, the originally created
316	     * owner is returned with {@code 200 OK} (carrying its {@code Location}) so the retry neither creates
317	     * a duplicate nor re-runs the create rules. A {@code null} or blank key, an unseen key, or a key
318	     * whose owner no longer exists yields {@code null}, signalling the caller to perform a normal create.
319	     *
320	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
321	     * @return the originally created owner as a {@code 200 OK} response, or {@code null} to create normally
322	     */
323	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
324	        if (isBlank(idempotencyKey)) {
325	            return null;
326	        }
327	        Integer ownerId = idempotentCreateOwnerIds.get(idempotencyKey);
328	        if (ownerId == null) {
329	            return null;
330	        }
331	        Owner owner = this.clinicService.findOwnerById(ownerId);
332	        if (owner == null) {
333	            return null;
334	        }
335	        HttpHeaders headers = new HttpHeaders();
336	        headers.setLocation(UriComponentsBuilder.newInstance()
337	            .path(OwnerMapper.OWNER_PATH_TEMPLATE).buildAndExpand(owner.getId()).toUri());
338	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
339	        applyBulkSignupWarning(ownerDto);
340	        applyCapacityWarning(ownerDto);
341	        applyRiskFlag(ownerDto);
342	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.OK);
343	    }
344	
345	    /**
346	     * Remembers the owner just created under its request's {@code Idempotency-Key}, so a later create
347	     * repeating that key is served the same owner ({@link #replayIdempotentCreate}). A {@code null} or
348	     * blank key is ignored, leaving that create non-idempotent.
349	     *
350	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
351	     * @param ownerId        the id of the owner that was just created
352	     */
353	    private void rememberIdempotentCreate(String idempotencyKey, Integer ownerId) {
354	        if (!isBlank(idempotencyKey)) {
355	            idempotentCreateOwnerIds.put(idempotencyKey, ownerId);
356	        }
357	    }
358	
359	    /**
360	     * Emits the immutable structured {@code OWNER_CREATED} event for a freshly created owner on the
361	     * {@code AUDIT} logger, serialized as a JSON object {@code {seq, ownerId, memberId,
362	     * membershipLevel, event}}. The {@code seq} is drawn from {@link #OWNER_CREATED_SEQ}, advancing by
363	     * one per create so the events carry a total order. The {@code memberId} field carries the owner's
364	     * current primary identifier ({@link #primaryIdentifier}) — the unified member id.
365	     *
366	     * @param owner the owner that was just created and saved
367	     */
368	    private void emitOwnerCreatedEvent(Owner owner) {
369	        OwnerCreatedEvent event = new OwnerCreatedEvent(
370	            OWNER_CREATED_SEQ.incrementAndGet(),
371	            owner.getId(),
372	            primaryIdentifier(owner),
373	            owner.getMembershipLevel());
374	        AUDIT.info("{}", AUDIT_MAPPER.writeValueAsString(event));
375	    }
376	
377	    /**
378	     * Enqueues a welcome notification for a freshly created owner by emitting a single line on the
379	     * {@code NOTIFY} logger carrying the new owner's id and member id.
380	     *
381	     * @param owner the owner that was just created and saved
382	     */
383	    private void enqueueWelcomeNotification(Owner owner) {
384	        NOTIFY.info("Welcome notification: ownerId={} memberId={}",
385	            owner.getId(), primaryIdentifier(owner));
386	    }
387	
388	    /**
389	     * Returns the owner's current primary identifier — the single value that externally names the
390	     * owner and is carried by the structured audit event. That is the unified {@code memberId}; this
391	     * is the one place to change should a later evolution replace it, so every consumer of the primary
392	     * identifier follows automatically.
393	     *
394	     * @param owner the owner whose primary identifier is wanted
395	     * @return the owner's current primary identifier
396	     */
397	    private String primaryIdentifier(Owner owner) {
398	        return owner.getMemberId();
399	    }
400	
401	    /**
402	     * Immutable structured audit event emitted on a successful owner create. Serialized to JSON on the
403	     * {@code AUDIT} logger, its component order fixes the field order {@code {seq, ownerId, memberId,
404	     * membershipLevel, schemaVersion, event}}. The {@code event} discriminator is always
405	     * {@code 'OWNER_CREATED'} and {@code schemaVersion} is always {@value #OWNER_CREATED_SCHEMA_VERSION}.
406	     * The {@code memberId} component holds the owner's current primary identifier
407	     * ({@link #primaryIdentifier}) — the unified, version-2 member id.
408	     *
409	     * @param seq             monotonically increasing sequence across all creates
410	     * @param ownerId         the new owner's id
411	     * @param memberId        the owner's current primary identifier
412	     * @param membershipLevel the owner's stored membership level
413	     * @param schemaVersion   the structured event's schema version, always 2
414	     */
415	    private record OwnerCreatedEvent(int seq, Integer ownerId, String memberId, Integer membershipLevel,
416	                                     int schemaVersion, String event) {
417	        private OwnerCreatedEvent(int seq, Integer ownerId, String memberId, Integer membershipLevel) {
418	            this(seq, ownerId, memberId, membershipLevel, OWNER_CREATED_SCHEMA_VERSION, "OWNER_CREATED");
419	        }
420	    }
