424	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
425	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
426	        if (currentOwner == null) {
427	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
428	        }
429	        currentOwner.setAddress(ownerFieldsDto.getAddress());
430	        currentOwner.setCity(ownerFieldsDto.getCity());
431	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
432	        currentOwner.setLastName(ownerFieldsDto.getLastName());
433	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
434	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
435	        this.clinicService.saveOwner(currentOwner);
436	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
437	    }
