611	    /**
612	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
613	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
614	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
615	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
616	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
617	     *
618	     * @param telephone the raw telephone value submitted by the client
619	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
620	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
621	     *                                     400 response
622	     */
623	    private String normalizeTelephone(String telephone) {
624	        String e164 = toE164(telephone);
625	        if (e164 == null) {
626	            throw new InvalidOwnerFieldsException(List.of("telephone"));
627	        }
628	        return e164;
629	    }
