631	    /**
632	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
633	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
634	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
635	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
636	     * and when the supplied country code is one with a known national-number length
637	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
638	     * number must have exactly that many digits.
639	     *
640	     * @param telephone the raw telephone value, possibly {@code null}
641	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
642	     */
643	    private String toE164(String telephone) {
644	        if (telephone == null) {
645	            return null;
646	        }
647	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
648	        boolean hasPlus = cleaned.startsWith("+");
649	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
650	        String nationalSignificant = hasPlus
651	            ? digits
652	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
653	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
654	            return null;
655	        }
656	        if (!hasValidNationalNumberLength(nationalSignificant)) {
657	            return null;
658	        }
659	        return "+" + nationalSignificant;
660	    }
661	
662	    /**
663	     * Checks the national-number length of an E.164 number (country code plus national significant
664	     * digits, no leading {@code '+'}) against the per-country requirement in
665	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
666	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
667	     * country code is not listed carries no per-country length requirement and is accepted.
668	     *
669	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
670	     *                            leading {@code '+'}
671	     * @return {@code true} if the national-number length is correct for the country code, or the
672	     *         country code has no listed requirement; {@code false} otherwise
673	     */
674	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
675	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
676	            .filter(nationalSignificant::startsWith)
677	            .max(Comparator.comparingInt(String::length))
678	            .orElse(null);
679	        if (countryCode == null) {
680	            return true;
681	        }
682	        int nationalLength = nationalSignificant.length() - countryCode.length();
683	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
684	    }
