686	    /**
687	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
688	     * is left unset. When a value is present it must be a syntactically valid address whose domain is
689	     * not on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the stored and
690	     * returned value is that address lower-cased.
691	     *
692	     * @param email the raw email value submitted by the client, or {@code null} if omitted
693	     * @return the lower-cased email, or {@code null} if none was supplied
694	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
695	     *                                     or its domain is a disposable-mail domain, yielding a 400
696	     *                                     response
697	     */
698	    private String normalizeEmail(String email) {
699	        if (email == null) {
700	            return null;
