732	    /**
733	     * Builds the owner's {@code memberId}, formatted {@code '<REGION><FY><HASH8><CHK>'} with no
734	     * separators, unifying the former customer code and membership number into a single value.
735	     * {@code REGION} is the region code derived from the owner's postcode ({@link #regionForPostcode},
736	     * {@code 'UNKNOWN'} when the postcode is absent or in no known range); {@code FY} is the two-digit
737	     * fiscal year (which starts on 1 July) of the business-day-adjusted {@code registrationDate};
738	     * {@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the owner's
739	     * normalized telephone followed by the last name (the same segment used by the region-and-hash
740	     * identity); and {@code CHK} is a single Luhn check digit computed over the digits of
741	     * {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW261A2B3C4D7'}). The identity carries no sequence
742	     * number, so the same postcode region, fiscal year, telephone and last name always yield the same
743	     * member id.
744	     *
745	     * <p>If the computed member id collides with an existing owner's {@code memberId}, it is
746	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it
747	     * unique, so distinct owners always receive distinct member ids.
748	     *
749	     * @param postcode         the owner's validated postcode, or {@code null} if none was supplied
750	     * @param telephone        the owner's normalized (E.164) telephone
751	     * @param lastName         the owner's last name
752	     * @param registrationDate the owner's business-day-adjusted registration date
753	     * @return the formatted, de-duplicated member id
754	     */
755	    private String generateMemberId(String postcode, String telephone, String lastName, LocalDate registrationDate) {
756	        String region = Owner.IDENTITY_VERSION_TAG + regionForPostcode(postcode);
757	        String fy = String.format("%02d", FiscalYear.of(registrationDate) % 100);
758	        String hash8 = hashHex(telephone + lastName, 8);
759	        String prefix = region + fy + hash8;
760	        String baseId = prefix + luhnCheckDigit(prefix);
761	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
762	            .map(Owner::getMemberId)
763	            .filter(Objects::nonNull)
764	            .collect(Collectors.toSet());
765	        if (!existingIds.contains(baseId)) {
766	            return baseId;
767	        }
768	        int n = 2;
769	        while (existingIds.contains(baseId + "-" + n)) {
770	            n++;
771	        }
772	        return baseId + "-" + n;
773	    }
774	
775	    /**
776	     * Computes a single Luhn check digit (0-9) over the digits contained in {@code value}. The standard
777	     * Luhn algorithm runs over the digits from right to left, doubling every second digit (subtracting
778	     * 9 when a doubled value exceeds 9); non-digit characters are skipped. This is the {@code <CHK>}
779	     * segment of a {@code memberId}, computed over the digits of its {@code <REGION><FY><HASH8>} prefix.
780	     *
781	     * @param value the value whose digits the check digit is computed over
782	     * @return the Luhn check digit, 0 to 9
783	     */
784	    private int luhnCheckDigit(String value) {
785	        int sum = 0;
786	        boolean dbl = true;
787	        for (int i = value.length() - 1; i >= 0; i--) {
788	            char c = value.charAt(i);
789	            if (c < '0' || c > '9') {
790	                continue;
791	            }
792	            int d = c - '0';
793	            if (dbl) {
794	                d *= 2;
795	                if (d > 9) {
796	                    d -= 9;
797	                }
798	            }
799	            sum += d;
800	            dbl = !dbl;
801	        }
802	        return (10 - (sum % 10)) % 10;
803	    }
