805	    /**
806	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
807	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
808	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
809	     * {@code <REGION>} segment baked into the {@code memberId}.
810	     *
811	     * @param postcode the owner's postcode, or {@code null}
812	     * @return the region code, or {@code 'UNKNOWN'}
813	     */
814	    private String regionForPostcode(String postcode) {
815	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
816	            return "UNKNOWN";
817	        }
818	        int value = Integer.parseInt(postcode);
819	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
820	            int[] range = entry.getValue();
821	            if (value >= range[0] && value <= range[1]) {
822	                return entry.getKey();
823	            }
824	        }
825	        return "UNKNOWN";
826	    }
