966	    /**
967	     * Reports whether an email address carries a disposable-adjacent domain: its domain (the part
968	     * after the last {@code @}, compared case-insensitively) is a subdomain of a listed disposable
969	     * mail provider ({@link #DISPOSABLE_EMAIL_DOMAINS}) — the lower-cased domain equals a listed
970	     * disposable domain or ends with {@code '.'} followed by one. Exact disposable domains are already
971	     * rejected at creation, so in practice this catches their subdomains, which slip past that
972	     * exact-match blocklist. A {@code null}, blank or address without a domain is not adjacent.
973	     *
974	     * @param email the owner's stored email address, or {@code null} if none
975	     * @return {@code true} if the email domain is disposable-adjacent
976	     */
977	    private boolean isDisposableAdjacentEmail(String email) {
978	        if (isBlank(email)) {
979	            return false;
980	        }
981	        int at = email.lastIndexOf('@');
982	        if (at < 0 || at == email.length() - 1) {
983	            return false;
984	        }
985	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
986	        return DISPOSABLE_EMAIL_DOMAINS.stream()
987	            .anyMatch(disposable -> domain.equals(disposable) || domain.endsWith("." + disposable));
988	    }
