990	    /**
991	     * Rolls a registration date forward to a business day. A date that falls on a Saturday, a Sunday
992	     * or a listed {@linkplain #PUBLIC_HOLIDAYS public holiday} is rolled forward one day at a time
993	     * until it reaches the next non-holiday weekday; a date already on a non-holiday weekday is
994	     * returned unchanged. This applies to the effective registration date whether it was supplied in
995	     * the request or defaulted to the server date, and the adjusted value is what gets stored as
996	     * {@code registrationDate} and feeds every value derived from it (such as the member id's
997	     * fiscal-year segment and the daily create-limit's per-day bucket).
998	     *
999	     * @param date the effective registration date, supplied or defaulted
1000	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
1001	     */
1002	    private LocalDate toBusinessDay(LocalDate date) {
1003	        LocalDate adjusted = date;
1004	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
1005	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY
1006	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
1007	            adjusted = adjusted.plusDays(1);
1008	        }
1009	        return adjusted;
1010	    }
