1012	    /**
1013	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
1014	     * owner's. The identity key — the SHA-256 hex digest of {@code '<normalizedTelephone>|<lowerEmail>
1015	     * |<soundex(lastName)>'} — is the single value that consolidates all duplicate detection: the
1016	     * previously separate telephone, email and household checks are all expressed through it. Because
1017	     * the telephone is part of the key, two owners with the same last name and postcode but different
1018	     * telephones have different identity keys and are both allowed (the second is a soft match); only a
1019	     * whole-key match is a duplicate. The owner being created already carries its normalized telephone,
1020	     * email and last name, and existing owners store the same normalized forms, so the keys are
1021	     * compared directly. Owners flagged deleted are ignored.
1022	     *
1023	     * @param owner the owner being created, with its telephone, email and last name already set
1024	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
1025	     *                                         yielding a 409 Conflict response
1026	     */
1027	    private void rejectDuplicateIdentity(Owner owner) {
1028	        String identityKey = owner.getIdentityKey();
1029	        boolean inUse = this.clinicService.findAllOwners().stream()
1030	            .filter(this::isNotDeleted)
1031	            .map(Owner::getIdentityKey)
1032	            .anyMatch(identityKey::equals);
1033	        if (inUse) {
1034	            throw new DuplicateOwnerIdentityException(identityKey);
1035	        }
1036	    }
1037	
1038	    /**
1039	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
1040	     * that is not a hard duplicate (its identity key is unique, so it has already passed
1041	     * {@link #rejectDuplicateIdentity}) yet whose {@code soundex(lastName)} and postcode both match an
1042	     * existing owner's. Because the telephone is part of the identity key, two owners that share a last
1043	     * name and postcode but carry different telephones have different identity keys, so the second is
1044	     * created as a soft match rather than rejected. When such a match exists the owner is created with
1045	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
1046	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
1047	     * {@code false} and {@code possibleDuplicateOf} is left unset.
1048	     *
1049	     * <p>An owner that declares household membership via {@code sharesHousehold} is never flagged: a
1050	     * declared household member is not a suspected duplicate. An owner without a postcode cannot match
1051	     * on postcode and so is never flagged.
1052	     *
1053	     * @param owner           the owner being created, with its telephone, email, postcode and last
1054	     *                        name already set
1055	     * @param sharesHousehold whether the owner declared itself a member of an existing household
1056	     */
1057	    private void applyPossibleDuplicate(Owner owner, boolean sharesHousehold) {
1058	        owner.setPossibleDuplicate(false);
1059	        if (sharesHousehold) {
1060	            return;
1061	        }
1062	        String postcode = owner.getPostcode();
1063	        if (postcode == null) {
1064	            return;
1065	        }
1066	        String soundex = owner.getLastNameSoundex();
1067	        String identityKey = owner.getIdentityKey();
1068	        Owner match = this.clinicService.findAllOwners().stream()
1069	            .filter(this::isNotDeleted)
1070	            .filter(existing -> !identityKey.equals(existing.getIdentityKey())
1071	                && soundex.equals(existing.getLastNameSoundex())
1072	                && postcode.equals(existing.getPostcode()))
1073	            .min(Comparator.comparingInt(Owner::getId))
1074	            .orElse(null);
1075	        if (match != null) {
1076	            owner.setPossibleDuplicate(true);
1077	            owner.setPossibleDuplicateOf(match.getId());
1078	        }
1079	    }
1080	
1081	    /**
1082	     * Caps the membership level of the owner being created so it cannot exceed one above the current
1083	     * maximum membership level among its existing household members. A household member is a live (not
1084	     * soft-deleted) owner carrying the same computed {@code householdId}. The owner's own derived level
1085	     * ({@link Owner#getDerivedMembershipLevel()}) is returned capped at that maximum plus one; when the
1086	     * owner belongs to no household, or no existing household member is found, no cap applies and the
1087	     * derived level is returned unchanged. The owner being created has not been saved yet, so it is
1088	     * never considered its own household member.
1089	     *
1090	     * @param owner the owner being created, with its household id and level-affecting fields set
1091	     * @return the membership level to store, capped to the household ceiling where one exists
1092	     */
1093	    private Integer cappedMembershipLevel(Owner owner) {
1094	        int derivedLevel = owner.getDerivedMembershipLevel();
1095	        String householdId = owner.getHouseholdId();
1096	        if (householdId == null || householdId.isBlank()) {
1097	            return derivedLevel;
1098	        }
1099	        OptionalInt maxHouseholdLevel = this.clinicService.findAllOwners().stream()
1100	            .filter(this::isNotDeleted)
1101	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
1102	            .mapToInt(Owner::getMembershipLevel)
1103	            .max();
1104	        if (maxHouseholdLevel.isEmpty()) {
1105	            return derivedLevel;
1106	        }
1107	        return Math.min(derivedLevel, maxHouseholdLevel.getAsInt() + 1);
1108	    }
1109	
1110	    /**
1111	     * Computes the owner's deterministic {@code householdId}: the first twelve upper-cased hex
1112	     * characters of the SHA-256 digest of the normalized last name and the postcode joined by a
1113	     * {@code '|'}. Because the value derives only from the last name and postcode, every owner that
1114	     * shares both automatically shares the same household id, so the household is keyed on
1115	     * {@code (lastName, postcode)} with no opt-in required. The last name is normalized for comparison
1116	     * (trimmed, internal whitespace collapsed, lower-cased) so values differing only in case or spacing
1117	     * still land in the same household.
1118	     *
1119	     * @param lastName the owner's last name
1120	     * @param postcode the owner's validated postcode, or {@code null} if none was supplied
1121	     * @return the derived household id, or {@code null} when the owner has no postcode and so belongs
1122	     *         to no postcode-keyed household
1123	     */
1124	    private String computeHouseholdId(String lastName, String postcode) {
1125	        if (postcode == null) {
1126	            return null;
1127	        }
1128	        return hashHex(Owner.IDENTITY_VERSION_TAG + "|" + normalizeForComparison(lastName) + "|" + postcode, 12);
1129	    }
1130	
1131	    /**
1132	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
1133	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
1134	     * the result is lower-cased.
1135	     *
1136	     * @param value the value to normalize, possibly {@code null}
1137	     * @return the normalized value, or an empty string if {@code value} is {@code null}
1138	     */
1139	    private String normalizeForComparison(String value) {
1140	        if (value == null) {
1141	            return "";
1142	        }
1143	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1144	    }
1145	
1146	    /**
1147	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
1148	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
1149	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
1150	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
1151	     * This normalized value is what gets stored and returned.
1152	     *
1153	     * @param address the raw address value submitted by the client, possibly {@code null}
1154	     * @return the normalized address, or an empty string if {@code address} is {@code null}
1155	     */
1156	    private String normalizeAddress(String address) {
1157	        if (address == null) {
1158	            return "";
1159	        }
1160	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
1161	        if (collapsed.isEmpty()) {
1162	            return collapsed;
1163	        }
1164	        String[] tokens = collapsed.split(" ");
1165	        StringBuilder normalized = new StringBuilder(collapsed.length());
1166	        for (int i = 0; i < tokens.length; i++) {
1167	            if (i > 0) {
1168	                normalized.append(' ');
1169	            }
1170	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1171	        }
1172	        return normalized.toString();
1173	    }
1174	
1175	    /**
1176	     * Reports whether the submitted owner supplies an address in either accepted form: a non-blank
1177	     * structured {@code addressLine1}, or a non-blank flat {@code address}. The structured form is
1178	     * preferred when present, but either satisfies the address requirement, keeping the create
1179	     * contract backward-compatible with earlier flat-address-only owners.
1180	     *
1181	     * @param ownerFieldsDto the submitted owner fields
1182	     * @return {@code true} if an address is supplied in either form
1183	     */
1184	    private boolean hasAddress(OwnerFieldsDto ownerFieldsDto) {
1185	        return !isBlank(ownerFieldsDto.getAddressLine1())
1186	            || !isBlank(normalizeAddress(ownerFieldsDto.getAddress()));
1187	    }
1188	
1189	    /**
1190	     * Applies the owner's address, preferring the structured form over the flat one. When a non-blank
1191	     * {@code addressLine1} is supplied, it and the optional {@code addressLine2} are normalized
1192	     * ({@link #normalizeAddress}) and stored, and the owner's composed {@code address} is set to the
1193	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
1194	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized
1195	     * and stored and the structured lines are left unset. This keeps earlier flat-address owners
1196	     * working while letting everything that reads the address use the composed, normalized value.
1197	     *
1198	     * @param owner          the owner being created
1199	     * @param ownerFieldsDto the submitted owner fields
1200	     */
1201	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
1202	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
1203	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
1204	            String line2 = isBlank(ownerFieldsDto.getAddressLine2())
1205	                ? null
1206	                : normalizeAddress(ownerFieldsDto.getAddressLine2());
1207	            owner.setAddressLine1(line1);
1208	            owner.setAddressLine2(line2);
1209	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
1210	        } else {
1211	            owner.setAddressLine1(null);
1212	            owner.setAddressLine2(null);
1213	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
1214	        }
1215	    }
1216	}
